//! Writes the generated Rust code for table schemas (M1 spec sections 3.3, 4.3, 4.4).

use proc_macro2::{Ident, Span, TokenStream};
use quote::{format_ident, quote};

use super::CodegenError;
use super::naming::FieldName;
use super::schema::{FieldSchema, FieldType, TableSchema};

/// Marker in the header of every generated file. `write_generated` only removes files with it.
pub const GENERATED_MARKER: &str = "@generated by `content-tool codegen`";
/// Name of the generated module root.
pub const MOD_FILE: &str = "mod.rs";
/// File extension of Rust sources.
pub const RUST_EXTENSION: &str = "rs";
/// Doc comment of the generated `SCHEMA_HASH` constant, the last item of `mod.rs`.
const SCHEMA_HASH_DOC: &str = " CRC32 of the generated table files (sorted by name) and of this file without this item. The content bundle header stores it.";

/// One generated source file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    /// File name inside the output folder.
    pub name: String,
    /// Full file text.
    pub contents: String,
}

/// Renders one file per table plus `mod.rs`, sorted by file name. `mod.rs` ends with
/// `SCHEMA_HASH`: the CRC32 of the table files (sorted by name) followed by `mod.rs` without that
/// last item.
pub fn render(
    schemas: &[TableSchema],
    client_build: &str,
) -> Result<Vec<GeneratedFile>, CodegenError> {
    if schemas.is_empty() {
        return Err(CodegenError::NoTables);
    }
    let header = format!(
        "// SPDX-License-Identifier: AGPL-3.0-or-later\n// {GENERATED_MARKER} from client build {client_build}. Do not edit.\n\n"
    );
    let mut files = schemas
        .iter()
        .map(|schema| {
            let name = format!("{}.{RUST_EXTENSION}", schema.module);
            let body = format_tokens(&name, table_tokens(schema))?;
            Ok(GeneratedFile {
                contents: format!("{header}{body}"),
                name,
            })
        })
        .collect::<Result<Vec<_>, CodegenError>>()?;
    files.sort_by(|left, right| left.name.cmp(&right.name));
    let root = format!("{header}{}", format_tokens(MOD_FILE, mod_tokens(schemas))?);
    let mut hasher = crc32fast::Hasher::new();
    for file in &files {
        hasher.update(file.contents.as_bytes());
    }
    hasher.update(root.as_bytes());
    let hash_item = format_tokens(MOD_FILE, schema_hash_tokens(hasher.finalize()))?;
    files.push(GeneratedFile {
        name: MOD_FILE.to_owned(),
        contents: format!("{root}{hash_item}"),
    });
    files.sort_by(|left, right| left.name.cmp(&right.name));
    Ok(files)
}

fn schema_hash_tokens(hash: u32) -> TokenStream {
    let value = syn::LitInt::new(&format!("{hash:#010x}"), Span::call_site());
    quote! {
        #[doc = #SCHEMA_HASH_DOC]
        pub const SCHEMA_HASH: u32 = #value;
    }
}

fn format_tokens(name: &str, tokens: TokenStream) -> Result<String, CodegenError> {
    let file: syn::File = syn::parse2(tokens).map_err(|error| CodegenError::Render {
        name: name.to_owned(),
        message: error.to_string(),
    })?;
    Ok(prettyplease::unparse(&file))
}

fn field_ident(name: &FieldName) -> Ident {
    if name.raw {
        Ident::new_raw(&name.text, Span::call_site())
    } else {
        Ident::new(&name.text, Span::call_site())
    }
}

fn field_type_tokens(field: &FieldSchema) -> TokenStream {
    let base = match field.ty {
        FieldType::Bool => quote!(bool),
        FieldType::I64 => quote!(i64),
        FieldType::F64 => quote!(f64),
        FieldType::String => quote!(String),
    };
    if field.numbered {
        quote!(std::collections::BTreeMap<u32, #base>)
    } else if field.optional {
        quote!(Option<#base>)
    } else {
        base
    }
}

fn field_doc(field: &FieldSchema) -> String {
    if field.numbered {
        format!(
            " Numbered columns `{base}1`, `{base}2`, \u{2026} (key = number).",
            base = field.column
        )
    } else {
        format!(" Column `{}`.", field.column)
    }
}

fn table_tokens(schema: &TableSchema) -> TokenStream {
    let struct_name = format_ident!("{}", schema.struct_name);
    let type_name = &schema.type_name;
    let struct_doc = format!(" One row of a `{type_name}` datasheet.");
    let fields = schema.fields.iter().map(|field| {
        let ident = field_ident(&field.name);
        let ty = field_type_tokens(field);
        let doc = field_doc(field);
        quote! { #[doc = #doc] pub #ident: #ty }
    });
    let fills = schema.fields.iter().map(|field| {
        let ident = field_ident(&field.name);
        let presence = if field.numbered {
            "numbered"
        } else if field.optional {
            "optional"
        } else {
            "required"
        };
        let method = format_ident!("{}_{}", presence, field.ty.method_suffix());
        let column = &field.column;
        quote! { #ident: row.#method(#column)? }
    });
    quote! {
        use crate::fill::{FillError, RowView};
        use crate::table::FromDatasheet;

        #[doc = #struct_doc]
        #[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
        pub struct #struct_name { #(#fields),* }

        impl FromDatasheet for #struct_name {
            const TYPE_NAME: &'static str = #type_name;
            fn from_row(row: &RowView<'_>) -> Result<Self, FillError> {
                Ok(Self { #(#fills),* })
            }
        }
    }
}

fn mod_tokens(schemas: &[TableSchema]) -> TokenStream {
    let modules: Vec<Ident> = schemas
        .iter()
        .map(|schema| format_ident!("{}", schema.module))
        .collect();
    let types: Vec<Ident> = schemas
        .iter()
        .map(|schema| format_ident!("{}", schema.struct_name))
        .collect();
    let docs: Vec<String> = schemas
        .iter()
        .map(|schema| format!(" Tables of type `{}`.", schema.type_name))
        .collect();
    quote! {
        #(mod #modules;)*
        #(pub use #modules::#types;)*

        use nw_formats::datasheet::Datasheet;

        use crate::fill::FillError;
        use crate::table::{FromDatasheet, Table, TableCounts};

        /// Every table of the content bundle, grouped by table type.
        #[derive(Debug, Clone, Default, PartialEq, serde::Serialize, serde::Deserialize)]
        pub struct Tables {
            #( #[doc = #docs] pub #modules: Vec<Table<#types>>, )*
        }

        impl Tables {
            /// Fills `sheet` into the table list of its type.
            pub fn insert_datasheet(&mut self, source_path: &str, sheet: &Datasheet) -> Result<(), FillError> {
                match sheet.type_name.as_str() {
                    #( #types::TYPE_NAME => self.#modules.push(Table::fill(source_path, sheet)?), )*
                    _ => {
                        return Err(FillError::UnknownTableType {
                            source_path: source_path.to_owned(),
                            type_name: sheet.type_name.clone(),
                        });
                    }
                }
                Ok(())
            }

            /// Counts tables and rows over all table types.
            pub fn counts(&self) -> TableCounts {
                let mut counts = TableCounts::default();
                #( counts.add(&self.#modules); )*
                counts
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const BUILD: &str = "22469132";

    fn field(column: &str, name: &str, raw: bool, ty: FieldType, optional: bool) -> FieldSchema {
        FieldSchema {
            column: column.into(),
            name: FieldName {
                text: name.into(),
                raw,
            },
            ty,
            optional,
            numbered: false,
        }
    }

    fn schemas() -> Vec<TableSchema> {
        vec![
            TableSchema {
                type_name: "MasterItemDefinitions".into(),
                struct_name: "MasterItemDefinitions".into(),
                module: "master_item_definitions".into(),
                fields: vec![
                    field("ItemID", "item_id", false, FieldType::String, false),
                    field("Tier", "tier", false, FieldType::I64, true),
                    field("Type", "type", true, FieldType::Bool, true),
                ],
            },
            TableSchema {
                type_name: "AffixData".into(),
                struct_name: "AffixData".into(),
                module: "affix_data".into(),
                fields: vec![field("Ratio", "ratio", false, FieldType::F64, false)],
            },
        ]
    }

    fn file<'a>(files: &'a [GeneratedFile], name: &str) -> &'a str {
        &files
            .iter()
            .find(|file| file.name == name)
            .unwrap()
            .contents
    }

    #[test]
    fn render_writes_one_file_per_table_plus_mod() {
        let files = render(&schemas(), BUILD).unwrap();
        let names: Vec<&str> = files.iter().map(|file| file.name.as_str()).collect();
        assert_eq!(
            names,
            vec!["affix_data.rs", "master_item_definitions.rs", "mod.rs"]
        );
        for file in &files {
            assert!(
                file.contents
                    .starts_with("// SPDX-License-Identifier: AGPL-3.0-or-later\n")
            );
            assert!(file.contents.contains(GENERATED_MARKER));
            assert!(file.contents.contains(BUILD));
        }
    }

    #[test]
    fn table_file_declares_struct_and_fill() {
        let files = render(&schemas(), BUILD).unwrap();
        let text = file(&files, "master_item_definitions.rs");
        for expected in [
            "pub struct MasterItemDefinitions",
            "pub item_id: String",
            "pub tier: Option<i64>",
            "pub r#type: Option<bool>",
            r#"row.required_string("ItemID")?"#,
            r#"row.optional_i64("Tier")?"#,
            r#"row.optional_bool("Type")?"#,
            r#"const TYPE_NAME: &'static str = "MasterItemDefinitions";"#,
        ] {
            assert!(text.contains(expected), "missing `{expected}` in:\n{text}");
        }
    }

    #[test]
    fn mod_file_lists_modules_and_dispatch() {
        let files = render(&schemas(), BUILD).unwrap();
        let text = file(&files, MOD_FILE);
        for expected in [
            "mod master_item_definitions;",
            "pub use master_item_definitions::MasterItemDefinitions;",
            "pub struct Tables",
            "MasterItemDefinitions::TYPE_NAME =>",
            "self.master_item_definitions",
            "counts.add(&self.affix_data);",
        ] {
            assert!(text.contains(expected), "missing `{expected}` in:\n{text}");
        }
    }

    #[test]
    fn struct_name_differs_from_type_name() {
        let schemas = vec![TableSchema {
            type_name: "Outpost_Data".into(),
            struct_name: "OutpostData".into(),
            module: "outpost_data".into(),
            fields: vec![field("Ratio", "ratio", false, FieldType::F64, false)],
        }];
        let files = render(&schemas, BUILD).unwrap();
        let table = file(&files, "outpost_data.rs");
        for expected in [
            "pub struct OutpostData",
            "impl FromDatasheet for OutpostData",
            r#"const TYPE_NAME: &'static str = "Outpost_Data";"#,
            "One row of a `Outpost_Data` datasheet.",
        ] {
            assert!(
                table.contains(expected),
                "missing `{expected}` in:\n{table}"
            );
        }
        let root = file(&files, MOD_FILE);
        for expected in [
            "pub use outpost_data::OutpostData;",
            "pub outpost_data: Vec<Table<OutpostData>>",
            "OutpostData::TYPE_NAME => {",
            "self.outpost_data.push(Table::fill(source_path, sheet)?)",
            "Tables of type `Outpost_Data`.",
        ] {
            assert!(root.contains(expected), "missing `{expected}` in:\n{root}");
        }
    }

    #[test]
    fn numbered_field_is_a_map_filled_by_base_name() {
        let schemas = vec![TableSchema {
            type_name: "LootBucketData".into(),
            struct_name: "LootBucketData".into(),
            module: "loot_bucket_data".into(),
            fields: vec![FieldSchema {
                numbered: true,
                ..field("Item", "item", false, FieldType::I64, false)
            }],
        }];
        let files = render(&schemas, BUILD).unwrap();
        let text = file(&files, "loot_bucket_data.rs");
        for expected in [
            "pub item: std::collections::BTreeMap<u32, i64>",
            r#"row.numbered_i64("Item")?"#,
            "Numbered columns `Item1`, `Item2`, \u{2026} (key = number).",
        ] {
            assert!(text.contains(expected), "missing `{expected}` in:\n{text}");
        }
    }

    #[test]
    fn mod_file_dispatch_has_no_type_name_literals() {
        let files = render(&schemas(), BUILD).unwrap();
        let text = file(&files, MOD_FILE);
        assert!(
            !text.contains(r#""MasterItemDefinitions""#),
            "type name literal in:\n{text}"
        );
    }

    /// Splits `mod.rs` into the text before the `SCHEMA_HASH` item and the item.
    fn split_schema_hash(root: &str) -> (&str, &str) {
        root.split_at(root.rfind(&format!("///{SCHEMA_HASH_DOC}")).unwrap())
    }

    #[test]
    fn mod_file_ends_with_the_schema_hash_of_all_files() {
        let files = render(&schemas(), BUILD).unwrap();
        let (body, item) = split_schema_hash(file(&files, MOD_FILE));
        let mut hasher = crc32fast::Hasher::new();
        for table in files.iter().filter(|file| file.name != MOD_FILE) {
            hasher.update(table.contents.as_bytes());
        }
        hasher.update(body.as_bytes());
        let expected = format!(
            "pub const SCHEMA_HASH: u32 = {:#010x};\n",
            hasher.finalize()
        );
        assert!(
            item.ends_with(&expected),
            "expected `{expected}` in:\n{item}"
        );
    }

    #[test]
    fn schema_hash_changes_with_a_field_type() {
        let mut changed = schemas();
        changed[1].fields[0].ty = FieldType::I64;
        let hash_item = |schemas: &[TableSchema]| {
            let files = render(schemas, BUILD).unwrap();
            split_schema_hash(file(&files, MOD_FILE)).1.to_owned()
        };
        assert_ne!(hash_item(&schemas()), hash_item(&changed));
    }

    #[test]
    fn render_is_deterministic() {
        assert_eq!(
            render(&schemas(), BUILD).unwrap(),
            render(&schemas(), BUILD).unwrap()
        );
    }

    #[test]
    fn render_without_tables_is_an_error() {
        assert!(matches!(render(&[], BUILD), Err(CodegenError::NoTables)));
    }
}
